//! Product editor theme tokens (assets/editor/markdown-theme.json, generated by
//! tools/import-editor-theme.mjs). Lengths keep their CSS unit: `em` values are
//! resolved against the consuming element's font size, like the browser.
use super::view::style::Edges;
use crate::typography::Scale;
use gpui::Rgba;
use serde::Deserialize;
use std::{collections::HashMap, sync::OnceLock};

#[derive(Clone, Debug, Deserialize)]
struct Token {
    raw: String,
    color: Option<String>,
    px: Option<f32>,
    number: Option<f32>,
    #[serde(rename = "box")]
    edges: Option<[f32; 4]>,
}

#[derive(Deserialize)]
struct Variant {
    tokens: HashMap<String, Token>,
    #[serde(default)]
    root: RootMetrics,
}

#[derive(Default, Deserialize)]
struct RootMetrics {
    /// Chromium's platform scrollbar, reserved on BOTH edges by the product.
    #[serde(default, rename = "scrollbarGutter")]
    scrollbar_gutter: f32,
    #[serde(default, rename = "readingWeights")]
    reading_weights: HashMap<String, f32>,
}

#[derive(Deserialize)]
struct File {
    variants: HashMap<String, Variant>,
}

pub struct Tokens {
    map: HashMap<String, Token>,
    pub scrollbar_gutter: f32,
    reading_weights: HashMap<String, f32>,
}

fn load(json: &str) -> HashMap<String, Tokens> {
    let file: File = serde_json::from_str(json).expect("editor theme tokens");
    file.variants
        .into_iter()
        .map(|(k, v)| {
            (
                k,
                Tokens {
                    map: v.tokens,
                    scrollbar_gutter: v.root.scrollbar_gutter,
                    reading_weights: v.root.reading_weights,
                },
            )
        })
        .collect()
}

/// The Markdown viewer's contract (`--po-md-*`, …).
fn variants() -> &'static HashMap<String, Tokens> {
    static ALL: OnceLock<HashMap<String, Tokens>> = OnceLock::new();
    ALL.get_or_init(|| load(include_str!("../../assets/editor/markdown-theme.json")))
}

/// The CSV viewer's contract (csv-table-editor.css).
fn csv_variants() -> &'static HashMap<String, Tokens> {
    static ALL: OnceLock<HashMap<String, Tokens>> = OnceLock::new();
    ALL.get_or_init(|| load(include_str!("../../assets/editor/csv-theme.json")))
}

fn key(dark: bool, scale: Scale) -> String {
    let scale = match scale {
        Scale::Small => "small",
        Scale::Medium => "medium",
        Scale::Large => "large",
    };
    format!("{}/{scale}", if dark { "dark" } else { "light" })
}

/// Parse `rgb()`, `rgba()` and `color(srgb r g b [/ a])` as computed by Chromium.
/// `top` painted over an opaque `bottom` (source-over), e.g. a translucent
/// tint over `var(--po-editor-bg)` in a layered `background`.
pub fn over(top: Rgba, bottom: Rgba) -> Rgba {
    let k = |t: f32, b: f32| t * top.a + b * (1. - top.a);
    Rgba {
        r: k(top.r, bottom.r),
        g: k(top.g, bottom.g),
        b: k(top.b, bottom.b),
        a: 1.,
    }
}

/// An authored CSS colour (inline HTML `style`): `#rgb`, `#rgba`,
/// `#rrggbb`, `#rrggbbaa`, `rgb()` / `rgba()` and the CSS basic colour
/// keywords (plus `orange`, `grey`). Anything else (`currentColor`,
/// functions of other spaces) is no colour.
pub fn parse_css_color(value: &str) -> Option<Rgba> {
    let v = value.trim().to_ascii_lowercase();
    if let Some(hex) = v.strip_prefix('#') {
        let digits: Vec<u8> = hex
            .chars()
            .map(|c| c.to_digit(16).map(|d| d as u8))
            .collect::<Option<_>>()?;
        let channel = |hi: u8, lo: u8| f32::from(hi * 16 + lo) / 255.;
        let (r, g, b, a) = match digits[..] {
            [r, g, b] => (channel(r, r), channel(g, g), channel(b, b), 1.),
            [r, g, b, a] => (channel(r, r), channel(g, g), channel(b, b), channel(a, a)),
            [r1, r2, g1, g2, b1, b2] => (channel(r1, r2), channel(g1, g2), channel(b1, b2), 1.),
            [r1, r2, g1, g2, b1, b2, a1, a2] => (
                channel(r1, r2),
                channel(g1, g2),
                channel(b1, b2),
                channel(a1, a2),
            ),
            _ => return None,
        };
        return Some(Rgba { r, g, b, a });
    }
    if let Some(inner) = v
        .strip_prefix("rgba(")
        .or_else(|| v.strip_prefix("rgb("))
        .and_then(|s| s.strip_suffix(')'))
    {
        let (rgb, alpha) = match inner.split_once('/') {
            Some((c, a)) => (c, Some(a.trim())),
            None => (inner, None),
        };
        let parts: Vec<&str> = rgb
            .split(|c: char| c == ',' || c.is_whitespace())
            .filter(|p| !p.is_empty())
            .collect();
        let alpha = alpha.or_else(|| parts.get(3).copied());
        let number = |p: &str| match p.strip_suffix('%') {
            Some(pct) => pct.parse::<f32>().ok().map(|n| n / 100.),
            None => p.parse::<f32>().ok().map(|n| n / 255.),
        };
        let a = match alpha {
            Some(a) => match a.strip_suffix('%') {
                Some(pct) => pct.parse::<f32>().ok()? / 100.,
                None => a.parse::<f32>().ok()?,
            },
            None => 1.,
        };
        return Some(Rgba {
            r: number(parts.first()?)?.clamp(0., 1.),
            g: number(parts.get(1)?)?.clamp(0., 1.),
            b: number(parts.get(2)?)?.clamp(0., 1.),
            a: a.clamp(0., 1.),
        });
    }
    let hex = match v.as_str() {
        "black" => 0x000000,
        "silver" => 0xc0c0c0,
        "gray" | "grey" => 0x808080,
        "white" => 0xffffff,
        "maroon" => 0x800000,
        "red" => 0xff0000,
        "purple" => 0x800080,
        "fuchsia" | "magenta" => 0xff00ff,
        "green" => 0x008000,
        "lime" => 0x00ff00,
        "olive" => 0x808000,
        "yellow" => 0xffff00,
        "navy" => 0x000080,
        "blue" => 0x0000ff,
        "teal" => 0x008080,
        "aqua" | "cyan" => 0x00ffff,
        "orange" => 0xffa500,
        _ => return None,
    };
    Some(gpui::rgb(hex))
}

pub fn parse_color(value: &str) -> Option<Rgba> {
    let v = value.trim();
    let (r, g, b, a) = if let Some(inner) = v
        .strip_prefix("color(srgb")
        .and_then(|s| s.strip_suffix(')'))
    {
        let (rgb, alpha) = inner
            .split_once('/')
            .map_or((inner, None), |(c, a)| (c, Some(a)));
        let n: Vec<f32> = rgb
            .split_whitespace()
            .filter_map(|x| x.parse().ok())
            .collect();
        (
            *n.first()?,
            *n.get(1)?,
            *n.get(2)?,
            alpha.and_then(|a| a.trim().parse().ok()).unwrap_or(1.),
        )
    } else {
        let inner = v
            .strip_prefix("rgba(")
            .or_else(|| v.strip_prefix("rgb("))?
            .strip_suffix(')')?;
        let n: Vec<f32> = inner
            .split(',')
            .filter_map(|x| x.trim().parse().ok())
            .collect();
        (
            *n.first()? / 255.,
            *n.get(1)? / 255.,
            *n.get(2)? / 255.,
            n.get(3).copied().unwrap_or(1.),
        )
    };
    Some(Rgba { r, g, b, a })
}

impl Tokens {
    pub fn get(dark: bool, scale: Scale) -> &'static Tokens {
        &variants()[&key(dark, scale)]
    }
    /// The content boundary's language, not the interface's language alone,
    /// selects the reading weight (typography/locales.css).
    pub fn reading_weight(&self, han: bool) -> f32 {
        self.reading_weights[if han { "zh-Hans" } else { "en" }]
    }
    pub fn csv(dark: bool, scale: Scale) -> &'static Tokens {
        &csv_variants()[&key(dark, scale)]
    }
    fn token(&self, name: &str) -> &Token {
        self.map
            .get(name)
            .unwrap_or_else(|| panic!("missing editor token {name}"))
    }
    pub fn color(&self, name: &str) -> Rgba {
        self.token(name)
            .color
            .as_deref()
            .and_then(parse_color)
            .unwrap_or_else(|| panic!("{name} is not a colour"))
    }
    /// A length in px; `em` values use `font_size` (the consuming element).
    pub fn len(&self, name: &str, font_size: f32) -> f32 {
        let t = self.token(name);
        if let Some(em) = t
            .raw
            .trim()
            .strip_suffix("em")
            .filter(|s| !s.ends_with('r'))
            .and_then(|s| s.trim().parse::<f32>().ok())
        {
            return em * font_size;
        }
        t.px.or(t.number)
            .unwrap_or_else(|| panic!("{name} is not a length"))
    }
    pub fn number(&self, name: &str) -> f32 {
        let t = self.token(name);
        t.number
            .or(t.px)
            .unwrap_or_else(|| panic!("{name} is not a number"))
    }
    #[cfg(test)]
    pub fn edges(&self, name: &str) -> Edges {
        self.edges_at(name, 16.)
    }
    /// A `padding`-style shorthand; a single `em` length uses `font_size`.
    pub fn edges_at(&self, name: &str, font_size: f32) -> Edges {
        let e = self.token(name).edges.unwrap_or_else(|| {
            let v = self.len(name, font_size);
            [v, v, v, v]
        });
        Edges::new(e[0], e[1], e[2], e[3])
    }
    pub fn raw(&self, name: &str) -> &str {
        self.token(name).raw.trim()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn tokens_resolve_units_and_colours() {
        let t = Tokens::get(true, Scale::Medium);
        assert_eq!(t.len("--po-md-content-size", 15.), 15.);
        assert!((t.len("--po-md-source-line-gap", 15.) - 3.75).abs() < 1e-4);
        assert_eq!(t.len("--po-md-h2-gap-after", 19.), 2.);
        assert_eq!(t.number("--po-md-h1-weight"), 600.);
        assert_eq!(t.raw("--po-md-inline-code-color"), "currentColor");
        let c = t.color("--po-md-code-block-background");
        assert!((c.r - 32. / 255.).abs() < 1e-4 && c.a == 1.);
        let sel = t.color("--po-md-selection-bg");
        assert!((sel.a - 0.28).abs() < 1e-4);
        assert_eq!(
            t.edges("--po-md-code-block-padding"),
            Edges::new(12., 14., 12., 14.)
        );
        assert_eq!(
            Tokens::get(false, Scale::Large).len("--po-md-content-size", 16.),
            16.
        );
    }
}
